use toasty::stmt::{Page, Value};
use utoipa::ToSchema;

#[derive(serde::Serialize, serde::Deserialize, ToSchema)]
pub struct SerializablePage<T> {
    pub items: Vec<T>,
    pub cursor: Option<i64>,
}

fn cursor_to_i64(cursor: Value) -> Option<i64> {
    cursor
        .as_record()
        .and_then(|record| record.first())
        .and_then(|field| field.to_i64())
}

impl<T> From<Page<T>> for SerializablePage<T> {
    fn from(page: Page<T>) -> Self {
        Self {
            items: page.items,
            cursor: page.next_cursor.and_then(cursor_to_i64),
        }
    }
}
